{
  "headword": "盛り上がる",
  "reading": "もりあがる",
  "definition_simple": "To get excited, lively, or swell upward.",
  "definition_standard": "To become excited or animated (as a party, conversation, or mood); to swell, rise, or bulge upward physically.",
  "pos": "v5r,vi",
  "semantic_class": "state_change",
  "example_sentences": [
    {
      "id": "ex_1",
      "tier": "T1",
      "sentence": "パーティーが盛り上がった。",
      "translation": "The party got lively."
    },
    {
      "id": "ex_2",
      "tier": "T1",
      "sentence": "会話が盛り上がる。",
      "translation": "The conversation becomes animated."
    },
    {
      "id": "ex_3",
      "tier": "T2",
      "sentence": "試合会場の雰囲気が一気に盛り上がった。",
      "translation": "The atmosphere at the match venue heated up all at once."
    },
    {
      "id": "ex_4",
      "tier": "T2",
      "sentence": "お酒が入ると、だんだん話が盛り上がってくる。",
      "translation": "When people drink alcohol, the conversation gradually gets more lively."
    },
    {
      "id": "ex_5",
      "tier": "T3",
      "sentence": "そのニュースを聞いて、クラス中が盛り上がった。",
      "translation": "Hearing that news, the whole class got excited."
    },
    {
      "id": "ex_6",
      "tier": "T3",
      "sentence": "地面が盛り上がって、ひび割れができた。",
      "translation": "The ground swelled upward and cracks formed."
    },
    {
      "id": "ex_7",
      "tier": "T4",
      "sentence": "皆で協力して作った文化祭の準備は、本番に向けて最高潮に盛り上がっていった。",
      "translation": "The preparation for the cultural festival, made together, reached a peak of excitement toward the actual event."
    },
    {
      "id": "ex_8",
      "tier": "T4",
      "sentence": "彼の筋肉はトレーニングの成果ではっきりと盛り上がっていた。",
      "translation": "His muscles were clearly bulging as a result of training."
    },
    {
      "id": "ex_9",
      "tier": "T5",
      "sentence": "長引く不況を吹き飛ばすような、社会全体を盛り上げるイベントが求められている。",
      "translation": "There is a call for events that will energize society as a whole, blowing away the prolonged recession."
    },
    {
      "id": "ex_10",
      "tier": "T6",
      "sentence": "幾重にも重なった山々が夕日を背景に黒く盛り上がって見えた。",
      "translation": "Layer upon layer of mountains appeared to swell darkly against the backdrop of the setting sun."
    }
  ],
  "morphological_forms": [
    {
      "form_name": "Te-form",
      "surface": "盛り上がって"
    },
    {
      "form_name": "Past",
      "surface": "盛り上がった"
    },
    {
      "form_name": "Negative",
      "surface": "盛り上がらない"
    },
    {
      "form_name": "Potential",
      "surface": "盛り上がれる"
    }
  ],
  "primary_collocate": "会話",
  "word_family_forms": [
    "盛り上げ",
    "盛り上げる"
  ],
  "syn_ant_candidates": {
    "synonyms": [
      "沸き立つ",
      "活気づく",
      "高まる"
    ],
    "antonyms": [
      "冷める",
      "沈静化する",
      "しぼむ"
    ]
  }
}
